import json
import sys
from pathlib import Path

def load_configs(file_paths):
    """Load and merge JSON config files."""
    merged_config = {}

    for file_path in file_paths:
        # Load the JSON file directly
        with open(file_path, 'r') as f:
            config = json.load(f)
            merged_config.update(config)

    return merged_config

def main():
    if len(sys.argv) < 2:
        print("Usage: python config_loader.py <config_file1> <config_file2> ...")
        sys.exit(1)

    config_files = sys.argv[1:]
    try:
        config = load_configs(config_files)
        print(json.dumps(config, indent=2))
    except FileNotFoundError as e:
        print(f"Error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
